-- 0362 PROD CHECK (before), read-only, ONE statement: npx --yes supabase@2.120.0 db query --linked -f scripts/ops/harness/news-kinds/before.sql
-- Wanted: 7 rows; every old_times 1 and new_times 0 (the live bodies are the bodies this file was cut against); made 0 (no leaf, kind or knob of 0362 yet);
-- head 20260818000361 (the deploy order is by number: 0357, 0358, 0360, 0361, then this file; what matters most is old_times 1).
-- Keep `bodies` (each cut body's md5 before). Generated by scripts/ops/harness/news-kinds/gen-checks.mjs from the migration's own hunks. The catalog, news_kinds and world_config's keys are read.
begin transaction read only;
with h(fn, ord, old, new) as (values
  ('cmd.do_sell(uuid,jsonb)'::text, 1, $h$  perform public.stats_live_add(jsonb_build_object('trades', 1, 'units', q.units, 'sold', round(q.total)::bigint));
$h$, $h$  perform public.stats_live_add(jsonb_build_object('trades', 1, 'units', q.units, 'sold', round(q.total)::bigint));
  -- 0362 (N4, docs/NEWS_AND_MARKERS.md 2.2): a big sale is news. The threshold first (one knob read, one comparison; 0 is off); public.news_big_trade only above it.
  if q.total >= nullif(public.wc_num('news_big_trade'), 0) then
    perform public.news_big_trade('BIG_SALE', f.player_id, f.port_id, g.id, q.units, q.total);
  end if;
$h$),
  ('cmd.do_buy(uuid,jsonb)'::text, 1, $h$  perform public.stats_live_add(jsonb_build_object('trades', 1, 'units', q.units, 'bought', round(q.total)::bigint));
$h$, $h$  perform public.stats_live_add(jsonb_build_object('trades', 1, 'units', q.units, 'bought', round(q.total)::bigint));
  -- 0362 (N4, docs/NEWS_AND_MARKERS.md 2.2): a big buy is news. The threshold first (one knob read, one comparison; 0 is off); public.news_big_trade only above it.
  if q.total >= nullif(public.wc_num('news_big_trade'), 0) then
    perform public.news_big_trade('BIG_BUY', f.player_id, f.port_id, g.id, q.units, q.total);
  end if;
$h$),
  ('public.tick_price_snapshot(timestamp with time zone)'::text, 1, $h$    get diagnostics v_hours = row_count;
    update public.price_rollup set hour_done = v_hour_now where one;
$h$, $h$    get diagnostics v_hours = row_count;
    update public.price_rollup set hour_done = v_hour_now where one;
    -- 0362 (N4): the hour that just closed against the hour before it: the largest moves are news (public.news_price_spikes). Only in the run that folded an hour.
    if v_hours > 0 then
      perform public.news_price_spikes(v_hour_now, p_now);
    end if;
$h$),
  ('voyage.settle(uuid,timestamp with time zone)'::text, 1, $h$  v_booked  bigint;    -- 0339: the gold she took from a cargo ship (public.pirate_loot_book)
$h$, $h$  v_booked  bigint;    -- 0339: the gold she took from a cargo ship (public.pirate_loot_book)
  v_cost0   bigint;    -- 0362: her cargo at what it cost, read before the raiders take their share (the news of the day says what they took)
$h$),
  ('voyage.settle(uuid,timestamp with time zone)'::text, 2, $h$        v_taken := voyage.raid_takes(v.id, d, p_fleet, v_outcome);
$h$, $h$        v_cost0 := public.fleet_stock_at_cost(p_fleet);   -- 0362: before they take it (public.fleet_unload drops a good's cost with its last tun)
        v_taken := voyage.raid_takes(v.id, d, p_fleet, v_outcome);
$h$),
  ('voyage.settle(uuid,timestamp with time zone)'::text, 3, $h$      v_payload := v_payload || jsonb_build_object('outcome', v_outcome, 'prose', v_prose,
$h$, $h$      -- 0362 (N5, docs/NEWS_AND_MARKERS.md 2.2): pirates are news, when the day cost her something: the cargo taken at what it cost, the ransom paid, a cargo ship's gold
      -- (public.news_pirates: a player's company always, a ship of the world at news_pirate_loss and up). The day's payload below is what it was.
      if v_outcome in ('PLUNDERED', 'STRIPPED') or (v_outcome = 'RANSOM' and v_ransom > 0) then
        perform public.news_pirates(v.id, d, f.player_id, v_outcome,
                  v_ransom + v_booked + case when v_outcome = 'RANSOM' then 0 else v_cost0 - public.fleet_stock_at_cost(p_fleet) end);
      end if;
      v_payload := v_payload || jsonb_build_object('outcome', v_outcome, 'prose', v_prose,
$h$),
  ('public.capital_gift_one(timestamp with time zone,uuid)'::text, 1, $h$    end;
  return jsonb_build_object('gifted', v_n, 'gift_ducats', v_d, 'gift_waiting', v_wait, 'failed', v_fail, 'notes', v_notes);
$h$, $h$    end;
  -- 0362 (N6, docs/NEWS_AND_MARKERS.md 2.2): a gift that was made is news (public.news_gift). After the gift's own sub-block, so the news never makes a gift a failed one.
  if v_n > 0 then
    perform public.news_gift(r.cap_id, r.player_id, r.capital, p_now);
  end if;
  return jsonb_build_object('gifted', v_n, 'gift_ducats', v_d, 'gift_waiting', v_wait, 'failed', v_fail, 'notes', v_notes);
$h$)
), d as (
  select h.*, replace(pg_get_functiondef(to_regprocedure(h.fn)), chr(13), '') as def from h
)
select fn, ord,
       (length(def) - length(replace(def, old, ''))) / length(old) as old_times,
       (length(def) - length(replace(def, new, ''))) / length(new) as new_times,
       (select count(*) from unnest(array['public.news_num(numeric)', 'public.news_good(uuid)', 'public.news_room(text)', 'public.news_big_trade(text,uuid,uuid,uuid,numeric,numeric)', 'public.news_price_spikes(timestamp with time zone,timestamp with time zone)', 'public.news_pirates(uuid,integer,uuid,text,numeric)', 'public.news_gift(uuid,uuid,bigint,timestamp with time zone)']) f where to_regprocedure(f) is not null)
         + (select count(*) from public.news_kinds k where k.kind = any (array['BIG_SALE', 'BIG_BUY', 'PRICE_SPIKE', 'PIRATES', 'CAPITAL_GIFT']))
         + (select count(*) from public.world_config c where c.key like 'news\_%') as made,
       (select jsonb_object_agg(f, md5(replace(pg_get_functiondef(to_regprocedure(f)), chr(13), ''))) from unnest(array['cmd.do_sell(uuid,jsonb)', 'cmd.do_buy(uuid,jsonb)', 'public.tick_price_snapshot(timestamp with time zone)', 'voyage.settle(uuid,timestamp with time zone)', 'public.capital_gift_one(timestamp with time zone,uuid)']) f) as bodies,
       (select max(version) from supabase_migrations.schema_migrations) as head
  from d order by fn, ord;
commit;
